<template><div class="page"><h1>{{ t('工作台') }}</h1><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(180px,1fr))"><div class="card card-b" v-for="[k,v] in metrics" :key="k"><div class="muted">{{ t(k) }}</div><h2>{{ v }}</h2></div></div><div class="grid" style="grid-template-columns:1fr 1fr;margin-top:18px"><div class="card card-b"><h3>{{ t('地块覆盖') }}</h3><el-table :data="stats"><el-table-column prop="suburb" :label="t('区域')"/><el-table-column prop="total" :label="t('地块')"/><el-table-column prop="registered" :label="t('已登记')"/><el-table-column prop="withOwnership" :label="t('有产权信息')"/></el-table></div><div class="card card-b"><h3>{{ t('最近市场导入') }}</h3><el-table :data="imports.slice(0,8)"><el-table-column prop="createdAt" :label="t('日期')"/><el-table-column prop="filename" :label="t('文件')"/><el-table-column prop="success" :label="t('成功')"/></el-table><h3>{{ t('Rex 状态') }}</h3><div v-for="[k,v] in Object.entries(overview?.rex||{})" :key="k">{{ k }} · {{ v }}</div></div></div></div></template><script setup>import {ref,onMounted,computed} from 'vue';import {api} from '../api';import {t} from '../i18n';const overview=ref(null),stats=ref([]),imports=ref([]);const metrics=computed(()=>overview.value ? [['账户',overview.value.users],['待审核',overview.value.pendingApprovals],['24 小时写入',overview.value.writes24h],...Object.entries(overview.value.counts)] : []);onMounted(async()=>{[overview.value,stats.value,imports.value]=await Promise.all([api('admin/overview'),api('admin/parcel-stats'),api('admin/market/imports')])})</script>
